const $=s=>document.querySelector(s);
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10H21M8 3V7M16 3V7M7 14H10M14 14H17M7 17H10"/>',practice:'<path d="M3 4Q8 2 12 5Q16 2 21 4V20Q16 18 12 21Q8 18 3 20ZM12 5V21"/>',tests:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4V2H15V4M9 10H15M9 14H15M9 18H13"/>',vocab:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 15L12 7L16 15M10 12H14M8 18H16"/>',review:'<path d="M4 7V3M4 7H8M4 7A9 9 0 1 1 3 15M12 7V12L15 14"/>',progress:'<path d="M4 3V21H22M8 16V12M13 16V7M18 16V4"/>'};
const navItems=[['dashboard','Overview'],['plan','My study plan'],['practice','Practice by part'],['tests','Mini-tests'],['vocab','Vocabulary'],['review','Mistake notebook'],['progress','My progress']];
const storageKey='toeic-path-v1';
const fresh=()=>({weeks:8,target:750,minutes:45,start:new Date().toISOString(),history:[],mistakes:[],known:[],vocabDays:[]});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(storageKey)||'{}')}}catch{state=fresh()}
let page='dashboard',quiz=null,clock=null,vocabIndex=0,flipped=false,filter='All',persistOK=true;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{persistOK=false;toast('Browser storage is unavailable. Keep this tab open and export your progress.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const niceDate=d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const attempts=()=>state.history.flatMap(h=>h.answers);
const accuracy=a=>a.length?Math.round(100*a.filter(x=>x.correct).length/a.length):0;
const activeDays=()=>new Set([...state.history.map(h=>dayKey(new Date(h.date))),...state.vocabDays]);
function streak(){let n=0,d=new Date(),days=activeDays();if(!days.has(dayKey(d)))d.setDate(d.getDate()-1);while(days.has(dayKey(d))){n++;d.setDate(d.getDate()-1)}return n}
function currentWeek(){return Math.min(state.weeks,Math.max(1,Math.floor((Date.now()-new Date(state.start))/604800000)+1))}
function stat(label,value,unit,caption,glyph){return `<div class="stat"><div class="stat-top">${label}<span class="glyph">${glyph}</span></div><strong>${value} <em>${unit}</em></strong><small>${caption}</small></div>`}
function title(eyebrow,heading,sub,extra=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="sub">${sub}</p></div>${extra}</div>`}
function renderNav(){ $('#nav').innerHTML=navItems.map(([key,label])=>`<a href="#${key}" class="${page===key?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>${label}</a>`).join('');$('#crumb').textContent=navItems.find(n=>n[0]===page)?.[1]||'Study preferences';}
const heroArt=`<svg viewBox="0 0 350 270" aria-hidden="true"><circle cx="211" cy="137" r="105" fill="#dce7cc"/><circle cx="211" cy="137" r="83" fill="none" stroke="#cbd9b7" stroke-dasharray="3 7"/><path d="M36 236H329" stroke="#bbcda8" stroke-width="2"/><path d="M77 221L70 148L159 137L168 221" fill="#658363"/><path d="M81 151L87 221H168L160 142Z" fill="#fffdf4"/><path d="M105 159L140 154M107 174L146 169M109 190L147 185" stroke="#c2cfb2" stroke-width="4"/><path d="M131 211L155 96L238 113L214 228Z" fill="#234f44"/><path d="M151 105L143 149L222 166L231 121Z" fill="#a5b78e"/><path d="M156 162L211 174M153 176L208 188M150 190L193 200" stroke="#779875" stroke-width="4"/><path d="M232 227L270 157L285 165L248 235Z" fill="#b58a51"/><path d="M270 157L278 143L293 151L285 165" fill="#edcba3"/><path d="M232 227L229 245L248 235" fill="#f8e4c2"/><path d="M229 245L232 235L238 240" fill="#234f44"/><path d="M295 218V117M294 162Q255 133 266 114Q293 119 295 151M297 144Q332 112 336 131Q334 151 297 161M295 192Q264 180 267 160Q289 162 295 185" fill="#8ba573" stroke="#8ba573" stroke-width="3"/><path d="M278 211H315L307 239H285Z" fill="#d0bc96"/><rect x="201" y="52" width="67" height="46" rx="7" fill="#fffdf5" transform="rotate(8 201 52)"/><path d="M218 75L228 85L247 65" stroke="#72915d" stroke-width="4" fill="none"/><path d="M53 88H70M61 80V97M296 65H308M302 59V71" stroke="#9eb786" stroke-width="2"/></svg>`;
function dashboard(){const a=attempts(),today=state.history.filter(h=>dayKey(new Date(h.date))===dayKey()),dailyCount=today.reduce((n,h)=>n+h.answers.length,0),days=activeDays(),end=new Date(state.start);end.setDate(end.getDate()+state.weeks*7);const weekStart=new Date();weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));
return title('YOUR NEXT CHAPTER',`${new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening'}, future achiever.`,`Let's make a little progress toward your TOEIC goal.`,`<span class="date-chip">◷ &nbsp; ${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span>`)+
`<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR ${state.weeks}-WEEK JOURNEY · WEEK ${currentWeek()}</div><h2>A little practice.<br>A bigger future.</h2><p>Your next milestone is closer than you think. Make time for yourself and your goals today.</p><button class="primary" data-start="daily">Start today's practice <span>↗</span></button></div><div class="hero-art">${heroArt}</div></section>
<div class="stat-grid">${stat('Your target',state.target,'/ 990','A goal to work toward','⚑')}${stat('Practice accuracy',a.length?accuracy(a)+'%':'—','',a.length?`${a.length} questions answered`:'Take a session to get started','◎')}${stat('Study streak',streak(),streak()===1?'day':'days','Build your everyday habit','♧')}${stat('Today’s practice',dailyCount,'questions',`${state.minutes} min daily study goal`,'◷')}</div>
<div class="dashboard-columns"><div><div class="section-head"><h2>Your focus for today</h2><a href="#plan">View study plan ↗</a></div><div class="task-list"><button class="task" data-start="part" data-part="2"><span class="task-icon">♬</span><span class="task-info"><b>Train your listening ear</b><small><span class="tag">Part 2</span>Question–Response · 6 questions</small></span><span class="arrow">↗</span></button><button class="task" data-start="part" data-part="5"><span class="task-icon">Aa</span><span class="task-info"><b>Build a stronger grammar foundation</b><small><span class="tag">Part 5</span>Incomplete Sentences · 8 questions</small></span><span class="arrow">↗</span></button><button class="task" data-page="vocab"><span class="task-icon">▤</span><span class="task-info"><b>A few new words, a little more confidence</b><small><span class="tag">Vocabulary</span>Business essentials · ${VOCAB.length-state.known.length} to learn</small></span><span class="arrow">↗</span></button></div></div><div><div class="section-head"><h2>Show up for yourself</h2><span class="eyebrow">THIS WEEK</span></div><div class="panel"><div style="display:flex;justify-content:space-between"><b style="font-size:12px">Consistency is your superpower</b><span style="color:#c29658">✦</span></div><div class="weekdays">${['M','T','W','T','F','S','S'].map((v,i)=>{let d=new Date(weekStart);d.setDate(d.getDate()+i);return `<div class="day ${days.has(dayKey(d))?'done':''} ${dayKey(d)===dayKey()?'today':''}">${v}<span>${days.has(dayKey(d))?'✓':d.getDate()}</span></div>`}).join('')}</div><div class="week-note">${streak()?`${streak()} day${streak()>1?'s':''} of showing up. Keep your momentum going.`:'One focused session is all it takes to start your streak.'}</div></div><div class="tip"><div class="eyebrow">✧ A SMALL STUDY TIP</div><p>Review why an answer is wrong. Understanding the trap is just as useful as finding the right answer.</p></div></div></div>
<div class="section-head section-spacer"><h2>Find your focus</h2><a href="#practice">Explore all 7 parts ↗</a></div><div class="parts-grid">${[2,3,5,7].map(p=>{let pa=a.filter(x=>BANK.find(q=>q.id===x.id)?.part===p);return `<button class="part-card" data-start="part" data-part="${p}"><span class="part-num">PART ${p} &nbsp; · &nbsp; ${PARTS[p][2].toUpperCase()}</span><h3>${PARTS[p][0]} <span style="float:right;color:#8fa37c">↗</span></h3><div class="bar"><span style="width:${accuracy(pa)}%"></span></div><small>${pa.length?`${accuracy(pa)}% accuracy · ${pa.length} answered`:'Your fresh start awaits'}</small></button>`}).join('')}</div><p class="note">Your study window ends around ${niceDate(end)}. <a href="#settings" class="link">Adjust your goal and schedule</a></p>`;
}
function practice(){return title('ONE SKILL AT A TIME','Make practice your strength.','Choose your focus. Learn from every answer.')+`<div class="filters">${['All','Listening','Reading'].map(f=>`<button class="pill ${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="practice-grid">${PARTS.map((p,i)=>p&&(filter==='All'||filter===p[2])?`<div class="panel practice-card"><span class="badge">PART ${i} · ${p[2]}</span><h3>${p[0]}</h3><p>${p[1]}.</p><small>${BANK.filter(q=>q.part===i).length} original questions · Explanations included</small><button class="primary" data-start="part" data-part="${i}">Practice this part <span>↗</span></button></div>`:'').join('')}</div><p class="note">Listening uses your browser's English text-to-speech voices. Part 1 uses illustrations for scene practice. These learning drills are not official exam recordings or photographs.</p>`}
function tests(){return title('A LITTLE CHALLENGE','Meet your next milestone.','Check your skills, practice pacing, and discover what to study next.')+`<div class="practice-grid"><div class="panel practice-card"><span class="badge">START HERE</span><h3>Quick skill check</h3><p>Two questions from each part to find a starting point for your training.</p><small>14 questions · Untimed · Review after each answer</small><button class="primary" data-start="diagnostic">Find my starting point ↗</button></div><div class="panel practice-card"><span class="badge">TIMED PRACTICE</span><h3>The 15-minute challenge</h3><p>A mixed mini-test. Answer independently, then review your results at the end.</p><small>20 questions · 15 minutes · All 7 parts</small><button class="primary" data-start="timed">Start mini-test ↗</button></div><div class="panel practice-card"><span class="badge">READING SPRINT</span><h3>Read. Think. Decide.</h3><p>Practice grammar, text completion, and reading with a little time pressure.</p><small>15 questions · 12 minutes · Parts 5–7</small><button class="primary" data-start="reading">Start reading sprint ↗</button></div></div><div class="panel section-spacer"><h3>Make room for a full rehearsal</h3><p class="sub">The real Listening & Reading test has 100 listening questions in about 45 minutes and 100 reading questions in 75 minutes. These shorter drills use our ${BANK.length}-question starter bank; repeated sessions reuse questions. For full-length rehearsal, use official preparation materials.</p><p class="note"><a class="link" href="https://www.ets.org/toeic/about/faq/product-specific-faq/toeic-listening-reading.html" target="_blank" rel="noopener">Explore the official ETS test format and resources ↗</a></p></div>`}
function phase(w){let n=w/state.weeks;return n<=.25?['Build your foundation','Start with accuracy. Learn question formats and core sentence patterns.',['Parts 1–2: listen for question words and common traps','Part 5: parts of speech, verb forms, and prepositions','Review explanations and learn 5–10 useful words a day']]:n<=.6?['Turn knowledge into a habit','Develop comprehension and give weaker skills extra attention.',['Parts 3–4: predict context and listen for paraphrases','Parts 6–7: connect sentences and locate supporting evidence','Alternate listening and reading; revisit your mistake notebook']]:n<=.85?['Find your rhythm','Work on pacing while keeping your reasoning clear.',['Take two timed mini-tests this week','Spend most review time on your lowest-accuracy part','Use official full-length materials for an endurance session']]:['Prepare with confidence','Consolidate your learning and rehearse your test-day routine.',['Complete a full official practice test under timed conditions','Review recurring mistakes and useful vocabulary','Check your test-center instructions; keep the final day light']]}
function plan(){return title('A ROUTINE THAT FITS YOUR LIFE','Your path, one week at a time.',`${state.weeks} weeks · ${state.minutes} minutes a day · Target ${state.target}`,`<a class="secondary" href="#settings">Adjust my plan ↗</a>`)+`<div class="panel" style="margin-bottom:23px"><h3>Your daily rhythm</h3><p class="sub">${Math.round(state.minutes*.4)} min listening + ${Math.round(state.minutes*.4)} min reading + ${state.minutes-2*Math.round(state.minutes*.4)} min reviewing mistakes and vocabulary. Aim for 5 focused days, one review day, and one rest day each week.</p></div><div class="week-grid">${Array.from({length:state.weeks},(_,i)=>{let w=i+1,[t,d,tasks]=phase(w);return `<div class="panel week-card" style="${w===currentWeek()?'border-color:#91a978;background:#f0f4e9':''}"><div class="eyebrow">WEEK ${w} ${w===currentWeek()?'· YOU ARE HERE':''}</div><h3>${t}</h3><p>${d}</p><ul>${tasks.map(t=>`<li>${t}</li>`).join('')}</ul><button class="text-btn" data-start="${w/state.weeks>.6?'timed':'daily'}">${w/state.weeks>.6?'Try a timed challenge':'Start a mixed practice'} ↗</button></div>`}).join('')}</div><p class="note">This schedule is a flexible study guide. Your target is a personal goal; practice accuracy is not an official TOEIC scaled score or a guaranteed outcome.</p>`}
function vocab(){let word=VOCAB[vocabIndex],known=state.known.includes(vocabIndex);return title('WORDS THAT OPEN DOORS','A stronger vocabulary starts here.',`${state.known.length} of ${VOCAB.length} words learned · Business English essentials`)+`<div class="bar"><span style="width:${state.known.length/VOCAB.length*100}%"></span></div><div class="panel vocab-card section-spacer"><div class="eyebrow">WORD ${vocabIndex+1} / ${VOCAB.length} ${known?'· LEARNED ✓':''}</div><h2>${word[0]}</h2>${flipped?`<p>${word[1]}</p><p style="color:#547443">${word[3]}</p><p><em>“${word[2]}”</em></p>`:'<p>Can you remember what this word means?</p>'}<div class="vocab-actions"><button class="secondary" data-action="speak-word">♬ Hear word</button><button class="primary" data-action="flip">${flipped?'Hide meaning':'Reveal meaning'} ↻</button></div></div><div class="vocab-actions"><button class="secondary" data-action="prev-word">← Previous</button><button class="primary" data-action="learn-word">${known?'Learned ✓ · Next':'I know this · Next'} →</button><button class="secondary" data-action="next-word">Keep learning →</button></div><p class="note" style="text-align:center">Reveal a meaning or mark a word learned to log today's vocabulary practice.</p>`}
function review(){let missed=state.mistakes.map(id=>BANK.find(q=>q.id===id)).filter(Boolean);return title('YOUR BEST LEARNING MATERIAL','Make mistakes work for you.',`${missed.length} question${missed.length!==1?'s':''} to revisit. A correct answer in a review session clears it from your notebook.`,missed.length?'<button class="primary" data-start="review">Practice my mistakes ↗</button>':'')+(missed.length?missed.map(q=>`<div class="panel review-item"><span class="badge">PART ${q.part} · ${PARTS[q.part][0]}</span><h3 style="margin-top:17px">${q.audio?'Listening question '+q.id:escapeHTML(q.prompt)}</h3>${q.audio?`<button class="secondary" data-listen="${q.id}">♬ Listen again</button>`:''}${q.passage?`<details><summary>Read the passage</summary><div class="passage">${escapeHTML(q.passage)}</div></details>`:''}<p><b>Correct answer: ${String.fromCharCode(65+q.answer)}</b>${q.part>2?' · '+escapeHTML(q.options[q.answer]):''}</p><p class="sub">${q.explanation}</p></div>`).join(''):`<div class="panel empty"><span style="font-size:42px;color:#8ca575">✧</span><h2 style="margin-top:20px">A fresh page for your progress.</h2><p>Questions you miss will appear here with explanations. Every mistake is a chance to learn something useful.</p><button class="primary" data-start="daily">Try a practice session ↗</button></div>`)}
function progress(){let a=attempts(),list=state.history.slice(-8),weak=[1,2,3,4,5,6,7].map(p=>({p,a:a.filter(x=>BANK.find(q=>q.id===x.id)?.part===p)})).filter(x=>x.a.length).sort((a,b)=>accuracy(a.a)-accuracy(b.a));return title('THE EFFORT ADDS UP','See how far you’ve come.','Your real practice history, one session at a time.')+`<div class="stat-grid">${stat('Questions answered',a.length,'','Across completed sessions','◎')}${stat('Overall accuracy',a.length?accuracy(a)+'%':'—','','Practice accuracy, not a scaled score','↗')}${stat('Completed sessions',state.history.length,'','Every session is a step forward','▤')}${stat('Study time',Math.round(state.history.reduce((n,h)=>n+h.seconds,0)/60),'min','Time in completed sessions','◷')}</div><div class="dashboard-columns"><div class="panel"><h3>Accuracy across recent sessions</h3>${list.length?`<div class="progress-chart">${list.map(h=>`<div class="chart-column" style="height:${Math.max(3,accuracy(h.answers))}%"><span>${accuracy(h.answers)}%</span><small>${niceDate(h.date)}</small></div>`).join('')}</div><div style="height:28px"></div>`:'<p class="note">Finish your first session to start your progress chart.</p>'}</div><div class="panel"><h3>Your next best step</h3><p class="sub">${weak.length?`Part ${weak[0].p} has your lowest practice accuracy (${accuracy(weak[0].a)}%). A focused session and careful review can help.`:'Start with the quick skill check to see which parts need more attention.'}</p><button class="primary" style="margin-top:22px" data-start="${weak.length?'part':'diagnostic'}" data-part="${weak[0]?.p||5}">${weak.length?'Practice Part '+weak[0].p:'Take a skill check'} ↗</button></div></div><div class="panel section-spacer"><h3>Session history</h3>${state.history.length?state.history.slice().reverse().slice(0,30).map(h=>`<div class="history-row"><span>${niceDate(h.date)} · ${escapeHTML(h.name)}</span><b>${accuracy(h.answers)}% accuracy</b><span>${h.answers.length} questions · ${Math.max(1,Math.round(h.seconds/60))} min</span></div>`).join(''):'<p class="note">Your completed sessions will appear here.</p>'}</div>`}
function settings(){return title('MAKE IT YOUR OWN','A plan that works for you.','Set your goal, choose your pace, and keep showing up.')+`<form id="settings-form" class="panel"><div class="form-grid"><label>Study duration<select name="weeks">${[4,8,12].map(w=>`<option value="${w}" ${state.weeks===w?'selected':''}>${w} weeks · ${w===4?'1 month':w===8?'2 months':'3 months'}</option>`).join('')}</select></label><label>Target TOEIC score<input name="target" type="number" min="10" max="990" step="5" value="${state.target}" required></label><label>Daily study time<select name="minutes">${[20,30,45,60,90,120].map(m=>`<option value="${m}" ${state.minutes===m?'selected':''}>${m} minutes</option>`).join('')}</select></label><label>Plan start date<input name="start" type="date" value="${dayKey(new Date(state.start))}" required></label></div><div class="settings-actions"><button class="primary" type="submit">Save my preferences ✓</button><button type="button" class="secondary" data-action="export">Export progress ↓</button></div><p class="note">Progress stays in this browser on this device. Export a backup to keep your history. ${persistOK?'':'Browser storage is currently unavailable.'}</p><label style="max-width:400px">Restore an exported backup<input id="import-file" type="file" accept="application/json,.json"></label><p class="note">Importing a backup replaces the progress currently stored in this browser.</p></form><div class="panel section-spacer"><h3>About your practice companion</h3><p class="sub">${BANK.length} original questions across all seven parts, plus ${VOCAB.length} vocabulary cards. Listening drills use synthetic speech, and Part 1 uses illustrations. This is an independent starter resource. It does not provide full-length official tests or convert practice results to TOEIC scaled scores.</p><p class="note">TOEIC is a registered trademark of ETS. This site is not endorsed by or affiliated with ETS. <a class="link" href="https://www.ets.org/toeic/about/faq/product-specific-faq/toeic-listening-reading.html" target="_blank" rel="noopener">Official test information ↗</a></p></div>`}
function stopAudio(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function speak(text){if(!('speechSynthesis'in window)){toast('Speech playback is unavailable in this browser. Use the transcript for this drill.');return}stopAudio();let u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.92;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'))||null;u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('Playback could not start. Try again or use the transcript.')};speechSynthesis.speak(u)}
function shuffle(a){const result=[...a];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function balanced(count){let bank=[];for(let p=1;p<=7;p++)bank.push(...shuffle(BANK.filter(q=>q.part===p)).slice(0,2));let ids=bank.map(q=>q.id);return bank.concat(shuffle(BANK.filter(q=>!ids.includes(q.id))).slice(0,count-bank.length)).sort((a,b)=>a.part-b.part)}
function start(kind,part=5){if(quiz&&!confirm('Leave your current session? Unfinished answers will not be saved.'))return;clearInterval(clock);stopAudio();let questions,name,limit=0;if(kind==='part'){questions=shuffle(BANK.filter(q=>q.part===part)).slice(0,8);name='Part '+part+' practice'}else if(kind==='review'){questions=shuffle(BANK.filter(q=>state.mistakes.includes(q.id))).slice(0,20);name='Mistake review'}else if(kind==='reading'){questions=shuffle(BANK.filter(q=>q.part>=5)).slice(0,15).sort((a,b)=>a.part-b.part);name='Reading sprint';limit=720}else{questions=balanced(kind==='timed'?20:14);name=kind==='timed'?'15-minute challenge':kind==='diagnostic'?'Quick skill check':'Daily mixed practice';if(kind==='timed')limit=900}if(!questions.length){toast('No questions to review yet.');return}quiz={kind,name,questions,index:0,answers:{},checked:false,start:Date.now(),limit,deadline:limit?Date.now()+limit*1000:null};renderQuiz();if(limit)clock=setInterval(()=>{if(!quiz)return;let remaining=Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=formatTime(remaining);if(remaining===0)finishQuiz()},500)}
function formatTime(seconds){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function renderQuiz(){renderNav();const q=quiz.questions[quiz.index],selected=quiz.answers[q.id],timed=quiz.limit>0;$('#main').innerHTML=`<div class="quiz"><div class="quiz-top"><button class="text-btn" data-action="exit-quiz">← Leave session</button><b>${quiz.name}</b>${timed?`<span class="timer" id="timer">${formatTime(Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000)))}</span>`:'<span class="badge">LEARNING MODE</span>'}</div><div class="bar"><span style="width:${(quiz.index+1)/quiz.questions.length*100}%"></span></div><div class="panel quiz-card section-spacer"><div class="eyebrow">PART ${q.part} · ${PARTS[q.part][0]} <span style="float:right">${quiz.index+1} / ${quiz.questions.length}</span></div>${q.scene?`<div class="scene section-spacer">${SCENES[q.scene]}</div>`:''}${q.audio?`<div class="audio-row"><button class="primary" data-action="listen">♬ Play audio</button><button class="secondary" data-action="stop-audio">Stop</button><small>English synthetic speech</small></div>${!timed||quiz.checked?`<details><summary>Show transcript (learning aid)</summary><div class="passage">${escapeHTML(q.audio)}</div></details>`:''}`:''}${q.passage?`<div class="passage">${escapeHTML(q.passage)}</div>`:''}<div class="question-text">${escapeHTML(q.prompt)}</div><div class="answers">${q.options.map((opt,i)=>`<button class="answer ${selected===i?'selected':''} ${quiz.checked&&i===q.answer?'correct':''} ${quiz.checked&&selected===i&&i!==q.answer?'wrong':''}" data-answer="${i}" ${quiz.checked?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${q.part<=2?'Response '+String.fromCharCode(65+i):escapeHTML(opt)}</button>`).join('')}</div>${quiz.checked?`<div class="explanation" role="status"><b>${selected===q.answer?'Well done.':'Keep learning.'} The answer is ${String.fromCharCode(65+q.answer)}.</b><br>${q.explanation}</div>`:''}<div class="quiz-actions">${timed?`<button class="secondary" data-action="prev-q" ${quiz.index===0?'disabled':''}>← Previous</button><button class="primary" data-action="next-q">${quiz.index===quiz.questions.length-1?'Review & submit':'Next question →'}</button>`:quiz.checked?`<small>Understanding the reason is the real progress.</small><button class="primary" data-action="next-q">${quiz.index===quiz.questions.length-1?'See my results':'Next question →'}</button>`:`<button class="secondary" data-action="skip-q">Skip question</button><button class="primary" data-action="check" ${selected===undefined?'disabled':''}>Check answer ✓</button>`}</div>${timed?'<p class="note">Answers are revealed after submission. You can go back to change an answer.</p>':''}</div></div>`;window.scrollTo({top:0,behavior:'instant'})}
function finishQuiz(){if(!quiz)return;clearInterval(clock);stopAudio();let result=quiz,answers=result.questions.map(q=>({id:q.id,chosen:result.answers[q.id]??null,correct:result.answers[q.id]===q.answer}));answers.forEach(a=>{if(!a.correct&&!state.mistakes.includes(a.id))state.mistakes.push(a.id);if(a.correct&&result.kind==='review')state.mistakes=state.mistakes.filter(id=>id!==a.id)});state.history.push({date:new Date().toISOString(),name:result.name,answers,seconds:Math.min(Math.round((Date.now()-result.start)/1000),result.limit||86400)});save();quiz=null;let correct=answers.filter(a=>a.correct).length;$('#main').innerHTML=`<div class="quiz"><div class="panel empty"><div class="eyebrow">A STEP FORWARD</div><h1>You showed up. That matters.</h1><div class="big-score">${accuracy(answers)}<span style="font-size:26px">%</span></div><p>${correct} of ${answers.length} correct · ${answers.filter(a=>a.chosen===null).length} unanswered<br>This is practice accuracy, not an official TOEIC score.</p><div class="vocab-actions"><a class="primary" href="#review">Open mistake notebook ↗</a><button class="secondary" data-page="progress">See my progress</button></div></div><h2 class="section-spacer" style="margin-bottom:20px">Learn from this session</h2>${result.questions.map((q,i)=>`<div class="panel review-item"><div class="eyebrow">QUESTION ${i+1} · PART ${q.part} · ${answers[i].correct?'CORRECT ✓':answers[i].chosen===null?'UNANSWERED':'REVIEW'}</div>${q.scene?`<div class="scene section-spacer">${SCENES[q.scene]}</div>`:''}${q.audio?`<details style="margin-top:18px"><summary>Listening transcript</summary><div class="passage">${escapeHTML(q.audio)}</div></details>`:''}${q.passage?`<details style="margin-top:18px"><summary>Read passage</summary><div class="passage">${escapeHTML(q.passage)}</div></details>`:''}<p><b>${escapeHTML(q.prompt)}</b></p><p>${answers[i].chosen===null?'No answer selected.':'Your answer: '+String.fromCharCode(65+answers[i].chosen)+'.'} Correct: ${String.fromCharCode(65+q.answer)}${q.part>2?' · '+escapeHTML(q.options[q.answer]):''}</p><p class="sub">${q.explanation}</p></div>`).join('')}</div>`;window.scrollTo(0,0)}
function render(){renderNav();const views={dashboard,practice,tests,plan,vocab,review,progress,settings};$('#main').innerHTML=(views[page]||dashboard)();$('#sidebar').classList.remove('open');window.scrollTo(0,0)}
function navigate(next){if(quiz){if(!confirm('Leave this session? Unfinished answers will not be saved.')){history.replaceState(null,'','#'+page);return}quiz=null;clearInterval(clock);stopAudio()}page=['dashboard','practice','tests','plan','vocab','review','progress','settings'].includes(next)?next:'dashboard';render()}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'dashboard'));
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')===location.hash){e.preventDefault();navigate(location.hash.slice(1)||'dashboard')}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.id==='mobile-menu'){$('#sidebar').classList.toggle('open');return}if(b.dataset.page){if(location.hash==='#'+b.dataset.page)navigate(b.dataset.page);else location.hash=b.dataset.page;return}if(b.dataset.start){start(b.dataset.start,Number(b.dataset.part||5));return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.listen){speak(BANK.find(q=>q.id===Number(b.dataset.listen)).audio);return}if(b.dataset.answer!==undefined&&quiz&&!quiz.checked){quiz.answers[quiz.questions[quiz.index].id]=Number(b.dataset.answer);const pos=window.scrollY;renderQuiz();window.scrollTo(0,pos);return}const action=b.dataset.action;if(!action)return;
if(action==='listen'&&quiz)speak(quiz.questions[quiz.index].audio);
if(action==='stop-audio')stopAudio();
if(action==='check'&&quiz){quiz.checked=true;renderQuiz()}
if(action==='prev-q'&&quiz&&quiz.index>0){quiz.index--;stopAudio();renderQuiz()}
if((action==='next-q'||action==='skip-q')&&quiz){if(quiz.index===quiz.questions.length-1){if(quiz.limit&&Object.keys(quiz.answers).length<quiz.questions.length&&!confirm('Some questions are unanswered. Submit this session anyway?'))return;finishQuiz()}else{quiz.index++;quiz.checked=false;stopAudio();renderQuiz()}}
if(action==='exit-quiz')navigate(page);
if(action==='flip'){flipped=!flipped;if(!state.vocabDays.includes(dayKey()))state.vocabDays.push(dayKey());save();render()}
if(action==='speak-word')speak(VOCAB[vocabIndex][0]+'. '+VOCAB[vocabIndex][2]);
if(action==='learn-word'){if(!state.known.includes(vocabIndex))state.known.push(vocabIndex);if(!state.vocabDays.includes(dayKey()))state.vocabDays.push(dayKey());save();vocabIndex=(vocabIndex+1)%VOCAB.length;flipped=false;render()}
if(action==='next-word'||action==='prev-word'){vocabIndex=(vocabIndex+(action==='next-word'?1:-1)+VOCAB.length)%VOCAB.length;flipped=false;render()}
if(action==='export'){const blob=new Blob([JSON.stringify({app:'toeic-path',version:1,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toeic-path-progress-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your progress backup has been exported.')}
});
document.addEventListener('submit',e=>{if(e.target.id!=='settings-form')return;e.preventDefault();let d=new FormData(e.target);state.weeks=Number(d.get('weeks'));state.target=Number(d.get('target'));state.minutes=Number(d.get('minutes'));state.start=new Date(d.get('start')+'T00:00:00').toISOString();save();toast('Your study preferences have been saved.');render()});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;try{const file=e.target.files[0];if(file.size>5e6)throw Error('too large');let data=JSON.parse(await file.text()),s=data.state;const validId=id=>Number.isInteger(id)&&BANK.some(q=>q.id===id);if(data.app!=='toeic-path'||data.version!==1||!s||![4,8,12].includes(s.weeks)||![20,30,45,60,90,120].includes(s.minutes)||!Number.isInteger(s.target)||s.target<10||s.target>990||s.target%5||!Number.isFinite(Date.parse(s.start))||!Array.isArray(s.history)||!s.history.every(h=>typeof h.name==='string'&&Number.isFinite(Date.parse(h.date))&&Number.isFinite(h.seconds)&&h.seconds>=0&&Array.isArray(h.answers)&&h.answers.every(a=>validId(a.id)&&typeof a.correct==='boolean'&&(a.chosen===null||(Number.isInteger(a.chosen)&&a.chosen>=0&&a.chosen<BANK.find(q=>q.id===a.id).options.length))))||!Array.isArray(s.mistakes)||!s.mistakes.every(validId)||!Array.isArray(s.known)||!s.known.every(i=>Number.isInteger(i)&&i>=0&&i<VOCAB.length)||!Array.isArray(s.vocabDays)||!s.vocabDays.every(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)))throw Error('invalid');if(confirm('Replace the progress on this device with this backup?')){state={...fresh(),...s,mistakes:[...new Set(s.mistakes)],known:[...new Set(s.known)]};save();render();toast('Your progress has been restored.')}}catch{toast('This file is not a valid TOEIC Path progress backup.')}});
window.addEventListener('beforeunload',e=>{if(quiz){e.preventDefault();e.returnValue=''}});
page=location.hash.slice(1)||'dashboard';if(!['dashboard','plan','practice','tests','vocab','review','progress','settings'].includes(page))page='dashboard';render();
